class _Failure(Exception):
    """fail() 抛出的内部异常：携带退出码与错误标签，由最外层统一落盘。"""

    def __init__(self, exit_code, label):
        super().__init__(label)
        self.exit_code = exit_code
        self.label = label


def fail(exit_code, label):
